export async function downloadCompanyDocument(companyId: string, documentId: string, fileName: string): Promise<void> {
  const tenantId = getActiveTenantId();
  const response = await fetch(`${API_URL}/companies/${companyId}/documents/${documentId}`, { credentials: 'include', headers: { Accept: 'application/octet-stream', ...(xsrfToken() ? { 'X-XSRF-TOKEN': decodeURIComponent(xsrfToken()!) } : {}), ...(tenantId ? { 'X-Tenant-Id': tenantId } : {}) } });
  if (!response.ok) { const body = await response.json().catch(() => ({})); throw new ApiError(response.status, body.message ?? `Download failed (${response.status}).`); }
  const blobUrl = URL.createObjectURL(await response.blob());
  const link = document.createElement('a'); link.href = blobUrl; link.download = fileName; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(blobUrl);
}
